SELECT
    concat('BR_', lpad(CAST(idx AS STRING), 2, '0')) AS `BR`,
    idx AS `ACCTNO`,
    idx AS `ACTYPE`,
    concat('SNAME_', lpad(CAST(idx AS STRING), 2, '0')) AS `SNAME`,
    idx AS `CIFNO`,
    concat('ALTADD_', lpad(CAST(idx AS STRING), 2, '0')) AS `ALTADD`,
    concat('ADDNAM_', lpad(CAST(idx AS STRING), 2, '0')) AS `ADDNAM`,
    concat('ALTNAM_', lpad(CAST(idx AS STRING), 2, '0')) AS `ALTNAM`,
    concat('OFFCR_', lpad(CAST(idx AS STRING), 2, '0')) AS `OFFCR`,
    concat('COFFCR_', lpad(CAST(idx AS STRING), 2, '0')) AS `COFFCR`,
    concat('STATUS__CS_', lpad(CAST(idx AS STRING), 2, '0')) AS `STATUS__CS`,
    concat('PRVSTS_', lpad(CAST(idx AS STRING), 2, '0')) AS `PRVSTS`,
    concat('CLASS_', lpad(CAST(idx AS STRING), 2, '0')) AS `CLASS`,
    concat('TYPE__CS_', lpad(CAST(idx AS STRING), 2, '0')) AS `TYPE__CS`,
    TRY_CAST(idx * 100.25 AS DECIMAL(38,10)) AS `ORGAMT`,
