    TRY_CAST(idx * 100.25 AS DECIMAL(38,10)) AS `PMTDU__CS`,
    concat('PDIREP_', lpad(CAST(idx AS STRING), 2, '0')) AS `PDIREP`,
    concat('PDIHIS_', lpad(CAST(idx AS STRING), 2, '0')) AS `PDIHIS`,
