    concat('PDDAYSREG_', lpad(CAST(idx AS STRING), 2, '0')) AS `PDDAYSREG`,
    TRY_CAST(idx * 100.25 AS DECIMAL(38,10)) AS `PMTDUREG__CS`,
    date_add(DATE '2026-01-01', idx - 1) AS `AsOfDate`,
